      tradeControls.innerHTML =
        selected && session
          ? `<div class="qr-action-row">${window.CARD_TRADE?.markup("card", selected.id) || ""}${window.CARD_QR?.button("card", selected.id, name(selected)) || ""}</div>`
          : "";
      if (!selected) return;
