        const elapsed = now - state.time;
        const speed = Math.max(-3.2, Math.min(3.2, (dx - state.dx) / Math.max(elapsed, 8)));
        const previous = state.velocity;
        state.velocity =
          previous == null || elapsed > 95 || Math.sign(previous) !== Math.sign(speed)
